<script setup lang="ts">
import { ref } from 'vue';
import BodyTeleport from './BodyTeleport.vue';

const props = defineProps<{ canManage: boolean; steps: Array<{ id: number | string; label: string }>; workflows: Array<{ id: number | string; label: string }>; users: Array<{ id: number | string; label: string }>; processing?: boolean }>();
const emit = defineEmits<{ submit: [action: 'reopen' | 'move' | 'reroute' | 'reassign', data: Record<string, unknown>] }>();
const dialog = ref<null | 'reopen' | 'move' | 'reroute' | 'reassign'>(null);
const data = ref({ target_step_id: '', workflow_id: '', approver_id: '', approver_ids: [] as Array<string | number>, remarks: '' });
function open(action: NonNullable<typeof dialog.value>) { dialog.value = action; data.value = { target_step_id: '', workflow_id: '', approver_id: '', approver_ids: [], remarks: '' }; }
function submit() { if (!dialog.value) return; emit('submit', dialog.value, { ...data.value }); dialog.value = null; }
</script>

<template>
    <section v-if="canManage" class="space-y-3 rounded-lg border border-border bg-card p-4 text-card-foreground"><div><h2 class="font-semibold">Administrator overrides</h2><p class="text-sm text-muted-foreground">Record a reason for every manual workflow change.</p></div><div class="flex flex-wrap gap-2"><ActionButton v-for="action in ['reopen', 'move', 'reroute', 'reassign'] as const" :key="action" type="button" variant="outline" @click="open(action)">{{ action === 'reroute' ? 'Change workflow' : action === 'reassign' ? 'Change approver' : action[0].toUpperCase() + action.slice(1) }}</ActionButton></div>
        <BodyTeleport><div v-if="dialog" class="fixed inset-0 z-50 flex items-end justify-center bg-foreground/50 p-0 sm:items-center sm:p-4" @click.self="dialog = null"><section role="dialog" aria-modal="true" aria-labelledby="override-title" class="w-full max-w-lg space-y-4 rounded-t-xl border border-border bg-card p-5 text-card-foreground sm:rounded-xl"><h3 id="override-title" class="text-lg font-semibold">{{ dialog === 'reroute' ? 'Change workflow' : dialog === 'reassign' ? 'Change approver' : dialog[0].toUpperCase() + dialog.slice(1) + ' workflow' }}</h3><label v-if="dialog === 'move'" class="grid gap-1 text-sm">Target step<select v-model="data.target_step_id" class="min-h-10 rounded-md border border-input bg-background px-3"><option value="">Choose a step</option><option v-for="step in steps" :key="step.id" :value="step.id">{{ step.label }}</option></select></label><label v-if="dialog === 'reroute'" class="grid gap-1 text-sm">Workflow<select v-model="data.workflow_id" class="min-h-10 rounded-md border border-input bg-background px-3"><option value="">Choose a workflow</option><option v-for="workflow in workflows" :key="workflow.id" :value="workflow.id">{{ workflow.label }}</option></select></label><label v-if="dialog === 'reroute'" class="grid gap-1 text-sm">New approvers<select v-model="data.approver_ids" multiple class="min-h-24 rounded-md border border-input bg-background p-2"><option v-for="user in users" :key="user.id" :value="user.id">{{ user.label }}</option></select></label><label v-if="dialog === 'reassign'" class="grid gap-1 text-sm">Approver<select v-model="data.approver_id" class="min-h-10 rounded-md border border-input bg-background px-3"><option value="">Choose a user</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.label }}</option></select></label><label class="grid gap-1 text-sm">Reason<textarea v-model="data.remarks" rows="3" required class="rounded-md border border-input bg-background p-3" /></label><div class="flex justify-end gap-2"><ActionButton type="button" variant="outline" @click="dialog = null">Cancel</ActionButton><ActionButton type="button" :disabled="processing || !data.remarks" @click="submit">Apply override</ActionButton></div></section></div></BodyTeleport>
    </section>
</template>
